package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LastTraceIdVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property last trace id of observed issue ")
  void test_last_trace_id_v_o_builder() {
    Assertions.assertFalse(LastTraceIdVO.nullValue().getLastTraceId().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LastTraceIdVO.tryFrom(null).getLastTraceId().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", LastTraceIdVO.from("one").getLastTraceId().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LastTraceIdVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LastTraceIdVO.from("one").toString());
  }
}
